def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
                desperate_count += 1
            if opp.get('budget', 0) >= 700:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    pressure = 0
    if supply <= 16:
        pressure += 2
    elif supply <= 18:
        pressure += 1

    if no_water_days >= 2:
        pressure += 3
    elif no_water_days >= 1:
        pressure += 1

    if hp <= 2:
        pressure += 3
    elif hp <= 4:
        pressure += 2
    elif hp <= 6:
        pressure += 1

    if desperate_count >= 2:
        pressure += 1

    if day >= 8:
        pressure += 1

    if pressure <= 1:
        bid = 16.0 if supply >= 20 else 22.0
        if highest_prev < 60:
            bid = max(bid, highest_prev + 2.0)
    elif pressure == 2:
        bid = 38.0
        if highest_prev > 0:
            bid = max(bid, min(72.0, highest_prev * 0.55))
    elif pressure == 3:
        bid = 68.0
        if highest_prev > 0:
            bid = max(bid, min(105.0, highest_prev * 0.72))
    elif pressure == 4:
        bid = 96.0
        if highest_prev > 0:
            bid = max(bid, min(145.0, highest_prev * 0.85))
    else:
        bid = 135.0
        if highest_prev > 0:
            bid = max(bid, min(185.0, highest_prev + 3.0))

    if supply >= 23 and pressure <= 2:
        bid *= 0.8
    elif supply <= 15:
        bid *= 1.2

    if avg_prev >= 150 and pressure <= 2:
        bid *= 0.85

    if rich_count >= 2 and pressure >= 3:
        bid *= 1.08

    if no_water_days == 0 and hp >= 8 and budget < 250:
        bid *= 0.85

    min_safe = 0.0
    if no_water_days >= 2 or hp <= 2:
        min_safe = 110.0
    elif no_water_days >= 1 or hp <= 4:
        min_safe = 70.0

    bid = max(bid, min_safe)
    bid = min(bid, budget)

    if budget < 80:
        bid = min(bid, max(22.0, budget * 0.92))

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))
